    font-weight: 500;
    color: #333;
  }
  p {
    margin: 0;
    font-size: 14px;
    font-weight: 400;
    color: #666;
  }
</style>
```
7. Render the component in your main app component:
```
<template>
  <div class="container">
    <h1>Anime Titles and Ratings</h1>
    <AnimeList />
  </div>
</template>

<script>
